  test("unknown ports are rejected", () => {
    assert.throws(() => localArrival(new Date("2026-01-15T09:30:00Z"), "XXZZZ"), RangeError);
  });

  test("Singapore is stamped in its own time zone, not UTC", () => {
    assert.equal(localArrival(new Date("2026-03-01T12:00:00Z"), "SGSIN"), "2026-03-01 20:00");
  });

  test("Rotterdam is stamped in its own time zone, not UTC", () => {
    assert.equal(localArrival(new Date("2026-03-01T12:00:00Z"), "NLRTM"), "2026-03-01 13:00");
  });
});

